// Embed the WebAssembly core as Base64 in a TypeScript module, so the
// package loads the same way in Node, browsers, Electron and bundlers
// (no file paths, no fetch of a .wasm asset).
//   node scripts/embed-wasm.mjs <p2f.wasm> <out.ts>
import { readFileSync, writeFileSync } from "node:fs";

const [input, output] = process.argv.slice(2);
let bytes;
try {
  bytes = readFileSync(input);
} catch {
  console.error(`${input} is missing. Build it first: make wasm (in the repository root).`);
  process.exit(1);
}
writeFileSync(
  output,
  "// Generated by scripts/embed-wasm.mjs from build/wasm/p2f.wasm. Do not edit.\n" +
    `export const WASM_BASE64 =\n  "${bytes.toString("base64")}";\n`,
);
console.log(`embedded ${bytes.length} bytes of WebAssembly`);
